mapper.select:
/* BmsMobPabsMapper.selectPkgNoInfo : 거대화물지정취소 - 박스번호조회 */
SELECT TOP 1 P.BL_NO , P.CARGO_REFERENCE_NO , PP.PACKING_NO , P.EX_CT , P.EX_WT , P.IN_YN , P.BIG_SIZE_YN , PP.IN_CT , P.IN_PLAN_NO , P.OD_JOB_NO , ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = P.INSPECTION_TYPE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y' AND ETC1='Y'), '') AS INSPECTION_TYPE FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO WHERE PP.PACKING_NO = #{srchNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
AND PP.DELETE_YN = 'N'
ORDER BY PP.IN_PLAN_NO

/* BmsMobPabsMapper.selectOneInPlanPkg : 박스번호조회 */ SELECT TOP 1 _inPlan.BL_NO , _inPlan.CARGO_REFERENCE_NO , _pkg.PACKING_NO , _inPlan.EX_CT , _inPlan.EX_WT , _inPlan.IN_YN , _inPlan.BIG_SIZE_YN , _pkg.IN_CT , _inPlan.IN_PLAN_NO , _inPlan.OD_JOB_NO , (SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = _inPlan.INSPECTION_TYPE AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y' AND ETC1='Y') AS INSPECTION_TYPE , (SELECT SUM(IN_CT) FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK) WHERE IN_PLAN_NO = _pkg.IN_PLAN_NO GROUP BY IN_PLAN_NO) AS IN_CT_SUM , _in.LAST_POD_STATUS , _in.IN_NO FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN _inPlan WITH (NOLOCK) ON _pkg.IN_PLAN_NO = _inPlan.IN_PLAN_NO LEFT JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_PLAN_NO = _inPlan.IN_PLAN_NO WHERE _pkg.DELETE_YN = 'N' AND _pkg.PACKING_NO = #{srchNo}
AND _pkg.IN_PLAN_NO = #{srchInPlanNo}
AND _inPlan.BL_NO = #{srchBlNo}

/* BmsMobPabsMapper.selectScanLogInfo : 스캔로그를 근거로 이미 거대지정/지정취소 여부 체크 */
SELECT COUNT(*) FROM TB_BMS_BIG_SIZE_SCAN
 WHERE BIG_SIZE_YN_INPUT = #{srchBigSizeYnInput}
   AND SCAN_RESULT = #{srchScanResult}
   AND SCAN_NO = #{srchNo}
   AND BL_NO = #{srchBlNo}
   AND BL_NO = (SELECT BL_NO FROM TB_BMS_IN_PLAN IP WITH (NOLOCK) WHERE IP.BIG_SIZE_YN = 'N' AND IP.IN_PLAN_NO = #{srchInPlanNo})

/* BmsMobPabsMapper.selectCountBmsInByInPlan : 반입예정번호로 반입있는지 체크 */
SELECT count(*) FROM TB_BMS_IN WITH (NOLOCK)
WHERE IN_PLAN_NO = #{inPlanNo}

mapper.insert:
/* BmsMobPabsMapper.insertBigSizeScanLog : 거대화물스캔로그 저장 */
INSERT INTO TB_BMS_BIG_SIZE_SCAN (
	  SCAN_NO
	, BL_NO
	, SCAN_DATE
	, SCAN_RESULT
	, BIG_SIZE_YN_INPUT
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	  #{packingNo}
	, #{blNo}
	, CONVERT(VARCHAR(10),GETDATE(),120)
	, #{scanResult}
	, #{bigSizeYnInput}
	, #{registerUserId}
	, GETDATE()
)

mapper.update:
/* BmsMobPabsMapper.updateBmsInPlanInYn */
update TB_BMS_IN_PLAN SET
	IN_YN       	  = #{inYn},
	UPDATE_USER_ID    = #{updateUserId},
	UPDATE_DATE_TIME  = GETDATE()
where IN_PLAN_NO = #{inPlanNo}

/* BmsMobPabsMapper.updateInPlanPkg : 박스 업데이트 */
UPDATE PP SET 
	PP.IN_CT = #{inCt}

		, BCR_TIME = CASE WHEN BCR_TIME IS NULL THEN GETDATE() ELSE BCR_TIME END
		, BCR_TIME_REIN = CASE WHEN BCR_TIME IS NOT NULL THEN GETDATE() ELSE NULL END 

FROM TB_BMS_IN_PLAN_PKG PP
JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
ON PP.IN_PLAN_NO = P.IN_PLAN_NO
WHERE PACKING_NO = #{packingNo}

AND PP.IN_PLAN_NO = #{srchInPlanNo}


AND P.BL_NO = #{srchBlNo}

/* BmsMobPabsMapper.updateBigSizeYnFromBmsInAndInPlan : 빅사이즈업데이트 */
UPDATE TB_BMS_IN_PLAN SET
	BIG_SIZE_YN = #{bigSizeYn}
	, UPDATE_USER_ID     = #{updateUserId}
	, UPDATE_DATE_TIME   = GETDATE()
WHERE IN_PLAN_NO = #{inPlanNo};

UPDATE TB_BMS_IN SET
	BIG_SIZE_YN = #{bigSizeYn}
	, UPDATE_USER_ID     = #{updateUserId}
	, UPDATE_DATE_TIME   = GETDATE()
WHERE IN_PLAN_NO = #{inPlanNo};

