/* BmsMobPabsMapper.selectInspectResultByTypeIsBigSize : 반입번호로 거대 검사결과 조회 */
SELECT 
	* 
FROM TB_BMS_INSPECT_RESULT 
WHERE IN_NO = #{inNo}
	AND INSPECTION_TYPE = 'B'

